/**
 * Touch input source: dual virtual sticks for mobile.
 *
 * The SECOND implementation of `LocomotionInputSource` — the desktop source
 * (src/input/desktopInput.ts) is the first. The controller core
 * (src/controller/firstPersonController.ts) is untouched: left stick maps to
 * `moveAxes()` (analog magnitudes < 1 preserved — the controller normalizes
 * only when length > 1), right stick maps to `consumeLookDelta()` pixels.
 *
 * Design notes (left stick moves, right stick looks, same controller core):
 * - CODE-SPLIT: this module is loaded via dynamic `import()` from main.ts
 *   only when the device is touch-primary (src/input/deviceDetection.ts).
 *   Desktop sessions never fetch this chunk; it contributes ZERO main-bundle
 *   bytes. It is DOM-only — NO `@babylonjs/*` imports (pinned by the
 *   requirements tier).
 * - The `LocomotionInputSource` contract is consumed via `import type` —
 *   erased at compile time, so this chunk has zero runtime coupling to the
 *   desktop input module.
 * - Overlays attach to `document.body`, NOT the canvas: the WebGPU→WebGL2
 *   fallback may REPLACE the canvas element (engine/bootstrap.ts), and the
 *   sticks must survive that. Knobs are separate fixed-position siblings
 *   (pointer-events: none) so every touch lands on the base ring.
 * - LOOK IS RATE-BASED: a held stick means "keep turning". The controller
 *   consumes look as raw pixels with no dt parameter, so this source converts
 *   deflection → px with an internal clock: deflection × TOUCH_LOOK_RATE_PX_PER_S
 *   × elapsed-since-last-consume, with elapsed CLAMPED to
 *   TOUCH_LOOK_MAX_CONSUME_S (0.1 s, mirroring MAX_TICK_DT_S) — a
 *   backgrounded tab must not bank seconds of "elapsed" and whip the camera
 *   on resume (a physical mouse can't accumulate unbounded deltas; a held
 *   stick can).
 * - Scroll/zoom prevention: `touch-action: none` inline on every
 *   overlay node PLUS non-passive `preventDefault()` on touchstart/touchmove
 *   — on the stick elements ONLY, never on document/window/body (the rest of
 *   the page keeps native behavior; the canvas already has touch-action:none
 *   from index.html).
 * - Each stick tracks its own pointer id: two concurrent pointers on two
 *   sticks never interfere; a second pointer on an already-active
 *   stick is ignored.
 * - Release is NOT allowed to depend on pointer capture:
 *   touch pointers get implicit capture to the base on pointerdown, but
 *   mouse/pen pointers do not, and `setPointerCapture` can be absent or
 *   throw — a pointer dragged off the base would then deliver its
 *   `pointerup` elsewhere and the deflection would latch forever. A
 *   release-only `pointerup`/`pointercancel` fallback therefore lives on the
 *   host document. It never calls preventDefault (the hosting page keeps
 *   native behavior); when capture works it is a harmless no-op.
 * - Everything registered here (stick elements AND the document fallback) is
 *   removed by `dispose()`, and both overlay node trees are removed from the
 *   DOM — HMR re-creates the module, and a leaked overlay means duplicate
 *   sticks on screen.
 */
import type { LocomotionInputSource, LookDelta, MoveAxes } from './desktopInput';
import { STICK_BASE_PX, STICK_INSET_PX, TOUCH_BUTTON_BOTTOM_PX, TOUCH_BUTTON_PX, touchButtonCss } from './touchButtons';

/** Set on the page's root while the sticks are shown, for its stylesheets to keep other things clear of them. */
export const TOUCH_MARK = 'data-webverse-touch';

export { STICK_BASE_PX, STICK_INSET_PX };

/** Radial deadzone (normalized): deflections at or inside it read as zero. */
export const TOUCH_STICK_DEADZONE = 0.15;
/**
 * Look rate at full deflection, in pixel-equivalents per second. Through the
 * controller's LOOK_SENSITIVITY_RAD_PER_PX (0.002) this is ≈ 2.4 rad/s
 * (~137°/s) — normal mobile-FPS feel. There is no tuning UI.
 */
export const TOUCH_LOOK_RATE_PX_PER_S = 1200;
/**
 * Elapsed-time clamp per `consumeLookDelta()` (mirrors the controller's
 * MAX_TICK_DT_S): a held stick over a backgrounded tab must not whip the
 * camera on resume.
 */
export const TOUCH_LOOK_MAX_CONSUME_S = 0.1;

/** Overlay geometry (px). Fixed-position, viewport-edge anchored. */
export const STICK_KNOB_PX = 56;

/**
 * Pure stick math: pointer offset from the stick center (screen px, +y down)
 * → deflection axes, magnitude clamped to 1 with a radial deadzone.
 *
 * Above the deadzone the magnitude is RE-SCALED so the deadzone edge maps to
 * 0 and the rim to 1 — no jump at the deadzone boundary — and direction is
 * preserved. Partial deflection keeps partial magnitude (analog walking).
 */
export function stickAxes(
  dxPx: number,
  dyPx: number,
  radiusPx: number,
  deadzone: number = TOUCH_STICK_DEADZONE,
): { x: number; y: number } {
  if (!(radiusPx > 0) || !Number.isFinite(dxPx) || !Number.isFinite(dyPx)) {
    return { x: 0, y: 0 };
  }
  const nx = dxPx / radiusPx;
  const ny = dyPx / radiusPx;
  const mag = Math.hypot(nx, ny);
  if (mag <= deadzone) return { x: 0, y: 0 };
  const clamped = Math.min(mag, 1);
  const scaled = (clamped - deadzone) / (1 - deadzone);
  return { x: (nx / mag) * scaled, y: (ny / mag) * scaled };
}

type Listener = (ev: Event) => void;

/**
 * Minimal element surface so unit tests can use plain-object doubles under
 * the node Vitest environment (no jsdom) — same pattern as desktopInput's
 * PointerLockCanvas/PointerLockDocument.
 */
export interface StickElement {
  addEventListener(type: string, listener: Listener, options?: { passive?: boolean }): void;
  removeEventListener(type: string, listener: Listener): void;
  remove(): void;
  setAttribute(name: string, value: string): void;
  getBoundingClientRect(): { left: number; top: number; width: number; height: number };
  setPointerCapture?(pointerId: number): void;
  readonly style: { cssText: string };
}

/** Minimal host (document) surface. Generic so `document` fits structurally. */
export interface OverlayHost<E extends StickElement = StickElement> {
  createElement(tagName: 'div'): E;
  body: { appendChild(child: E): unknown };
  /**
   * Release fallback seam: `pointerup`/`pointercancel` listeners registered
   * at the document level (release-only, never preventDefault) so a pointer
   * that escaped the base without capture still ends its gesture.
   */
  addEventListener(type: string, listener: Listener): void;
  removeEventListener(type: string, listener: Listener): void;
  /** The page's root, marked with TOUCH_MARK while the sticks are shown. */
  documentElement?: { setAttribute(name: string, value: string): void; removeAttribute(name: string): void };
}

export interface TouchInputOptions {
  /** Clock for the look-rate integration (injectable for tests). */
  now?: () => number;
  /**
   * The buttons the world wants (profiles/client-hints.md,
   * `controls.touch-buttons`), read live. Absent → jump and fly.
   */
  buttons?: () => readonly string[];
  /** Flying is allowed here (the world's `modes`, or the visitor's override). Absent → no. */
  flyAllowed?: () => boolean;
  /** The visitor is flying now. */
  flying?: () => boolean;
  /** The Fly button was tapped: toggle flight, as F does. */
  onFlyToggle?: () => void;
}

export interface TouchInput extends LocomotionInputSource {
  /** Touch has no pointer lock — always false (keeps main.ts's hook shape). */
  isPointerLocked(): boolean;
  /** Touch has no keyboard; `Input.GetKeyValue` is always false here. */
  isKeyDown(key: string): boolean;
  /** Re-read which buttons show and what they say (a hint changed, flight began). */
  refresh(): void;
  dispose(): void;
}

/** The pointer/touch event fields this module reads (doubles stay plain). */
interface StickPointerEvent {
  pointerId?: number;
  clientX?: number;
  clientY?: number;
  preventDefault?: () => void;
}

const KNOB_CENTER_INSET_PX = STICK_INSET_PX + (STICK_BASE_PX - STICK_KNOB_PX) / 2;

function baseCss(side: 'left' | 'right'): string {
  return (
    `position:fixed;bottom:${STICK_INSET_PX}px;${side}:${STICK_INSET_PX}px;` +
    `width:${STICK_BASE_PX}px;height:${STICK_BASE_PX}px;border-radius:50%;` +
    'background:rgba(255,255,255,0.08);border:2px solid rgba(255,255,255,0.25);' +
    'box-sizing:border-box;touch-action:none;user-select:none;' +
    '-webkit-user-select:none;-webkit-tap-highlight-color:transparent;z-index:10;'
  );
}

function knobCss(side: 'left' | 'right'): string {
  return (
    `position:fixed;bottom:${KNOB_CENTER_INSET_PX}px;${side}:${KNOB_CENTER_INSET_PX}px;` +
    `width:${STICK_KNOB_PX}px;height:${STICK_KNOB_PX}px;border-radius:50%;` +
    'background:rgba(255,255,255,0.35);touch-action:none;pointer-events:none;' +
    'z-index:11;'
  );
}

export function createTouchInput<E extends StickElement>(
  host: OverlayHost<E>,
  options: TouchInputOptions = {},
): TouchInput {
  const now = options.now ?? (() => performance.now());

  interface StickState {
    base: E;
    knob: E;
    knobBase: string;
    /** The captured pointer id, or null while untouched. */
    pointerId: number | null;
    centerX: number;
    centerY: number;
    radiusPx: number;
    /** Deadzone-scaled deflection, SCREEN convention (+x right, +y down). */
    x: number;
    y: number;
    registered: Array<[string, Listener]>;
    /** Release-if-matching handler, exposed for the document-level fallback. */
    endByEvent: Listener;
  }

  const makeStick = (kind: 'move' | 'look', side: 'left' | 'right'): StickState => {
    const base = host.createElement('div');
    base.setAttribute('data-webverse-stick', kind);
    // Pointer-only visuals: hidden from assistive tech so screen readers
    // don't announce anonymous blobs over the canvas.
    base.setAttribute('aria-hidden', 'true');
    base.style.cssText = baseCss(side);
    const knob = host.createElement('div');
    knob.setAttribute('data-webverse-stick-knob', kind);
    knob.setAttribute('aria-hidden', 'true');
    const knobBase = knobCss(side);
    knob.style.cssText = knobBase;
    host.body.appendChild(base);
    host.body.appendChild(knob);

    const st: StickState = {
      base,
      knob,
      knobBase,
      pointerId: null,
      centerX: 0,
      centerY: 0,
      radiusPx: STICK_BASE_PX / 2,
      x: 0,
      y: 0,
      registered: [],
      endByEvent: () => undefined, // assigned below once `end` exists
    };

    const update = (ev: StickPointerEvent): void => {
      const dx = (ev.clientX ?? st.centerX) - st.centerX;
      const dy = (ev.clientY ?? st.centerY) - st.centerY;
      const axes = stickAxes(dx, dy, st.radiusPx);
      st.x = axes.x;
      st.y = axes.y;
      // Knob visual: raw offset clamped to the base radius.
      const rawMag = Math.hypot(dx, dy);
      const vis = rawMag > st.radiusPx ? st.radiusPx / rawMag : 1;
      st.knob.style.cssText =
        st.knobBase + `transform:translate(${dx * vis}px,${dy * vis}px);`;
    };

    const release = (): void => {
      st.pointerId = null;
      st.x = 0;
      st.y = 0;
      st.knob.style.cssText = st.knobBase;
    };

    const on = (type: string, listener: Listener, opts?: { passive?: boolean }): void => {
      base.addEventListener(type, listener, opts);
      st.registered.push([type, listener]);
    };

    on('pointerdown', (ev) => {
      const p = ev as unknown as StickPointerEvent;
      if (st.pointerId !== null) return; // second pointer on an active stick: ignored
      p.preventDefault?.();
      const id = p.pointerId ?? 0;
      st.pointerId = id;
      try {
        base.setPointerCapture?.(id);
      } catch {
        /* capture can legitimately fail (absent API, inactive pointer) —
           the document-level release fallback below still ends the gesture */
      }
      const rect = base.getBoundingClientRect();
      st.centerX = rect.left + rect.width / 2;
      st.centerY = rect.top + rect.height / 2;
      st.radiusPx = Math.max(rect.width, rect.height) / 2 || STICK_BASE_PX / 2;
      update(p);
    });
    on('pointermove', (ev) => {
      const p = ev as unknown as StickPointerEvent;
      if (st.pointerId === null || (p.pointerId ?? 0) !== st.pointerId) return;
      update(p);
    });
    const end: Listener = (ev) => {
      const p = ev as unknown as StickPointerEvent;
      if (st.pointerId === null || (p.pointerId ?? 0) !== st.pointerId) return;
      release();
    };
    on('pointerup', end);
    on('pointercancel', end);
    st.endByEvent = end;
    // Belt-and-braces scroll/zoom prevention on the stick elements ONLY:
    // touch-action:none is the primary mechanism (it is also what suppresses
    // double-tap zoom — that would otherwise need touchend prevention);
    // non-passive preventDefault stops any residual scroll-starting gesture
    // (e.g. pull-to-refresh) from beginning on a stick. Never registered on
    // document/window/body.
    const prevent: Listener = (ev) => {
      (ev as unknown as StickPointerEvent).preventDefault?.();
    };
    on('touchstart', prevent, { passive: false });
    on('touchmove', prevent, { passive: false });

    return st;
  };

  const move = makeStick('move', 'left');
  const look = makeStick('look', 'right');

  // Jump, above the look stick: what Space does. A press is one jump
  // (edge) and holds while held (level: hold-to-keep-jumping, and ascend in
  // flight). Fly above it (shown only where flying is allowed) does
  // what F does, and Down beside it appears while flying. Each owns its
  // pointer the way a stick does, and lets go through the same
  // document-level fallback. A hidden button does nothing.
  interface Button {
    el: E;
    pointer: number | null;
    shown: boolean;
    registered: Array<[string, Listener]>;
    end: Listener;
  }
  const makeButton = (name: string, label: string, css: string, onPress?: () => void, onRelease?: () => void): Button => {
    const el = host.createElement('div');
    el.setAttribute('data-webverse-touch-button', name);
    el.setAttribute('role', 'button');
    el.setAttribute('aria-label', label);
    (el as unknown as { textContent: string }).textContent = label;
    el.style.cssText = css;
    host.body.appendChild(el);
    const b: Button = { el, pointer: null, shown: true, registered: [], end: () => undefined };
    const on = (type: string, listener: Listener, opts?: { passive?: boolean }): void => {
      el.addEventListener(type, listener, opts);
      b.registered.push([type, listener]);
    };
    on('pointerdown', (ev) => {
      const p = ev as unknown as StickPointerEvent;
      if (b.pointer !== null || !b.shown) return;
      p.preventDefault?.();
      b.pointer = p.pointerId ?? 0;
      try {
        el.setPointerCapture?.(b.pointer);
      } catch {
        /* the document fallback still ends it */
      }
      onPress?.();
    });
    b.end = (ev) => {
      const p = ev as unknown as StickPointerEvent;
      if (b.pointer === null || (p.pointerId ?? 0) !== b.pointer) return;
      b.pointer = null;
      onRelease?.();
    };
    on('pointerup', b.end);
    on('pointercancel', b.end);
    const prevent: Listener = (ev) => {
      (ev as unknown as StickPointerEvent).preventDefault?.();
    };
    on('touchstart', prevent, { passive: false });
    on('touchmove', prevent, { passive: false });
    return b;
  };

  let jumpPressed = false;
  const jump = makeButton('jump', 'Jump', touchButtonCss('right'), () => {
    jumpPressed = true;
  });
  const fly = makeButton('fly', 'Fly', touchButtonCss('right', undefined, TOUCH_BUTTON_BOTTOM_PX + TOUCH_BUTTON_PX + 12), undefined, () => {
    options.onFlyToggle?.();
    refresh();
  });
  const down = makeButton('down', 'Down', touchButtonCss('right', STICK_INSET_PX + STICK_BASE_PX + 12));
  const buttons = [jump, fly, down];

  /** Which buttons show and what they say; writes the page only when that changes. */
  let drawn = '';
  const show = (b: Button, on: boolean, css: string, label: string): void => {
    b.shown = on;
    if (!on) b.pointer = null;
    b.el.style.cssText = on ? css : css + 'display:none;';
    b.el.setAttribute('aria-label', label);
    (b.el as unknown as { textContent: string }).textContent = label;
  };
  const refresh = (): void => {
    const list = options.buttons?.() ?? ['jump', 'fly'];
    const flying = options.flying?.() ?? false;
    const canFly = options.flyAllowed?.() ?? false;
    const jumpOn = list.includes('jump') || flying;
    const flyOn = (list.includes('fly') && canFly) || flying;
    const state = `${jumpOn}|${flyOn}|${flying}`;
    if (state === drawn) return;
    drawn = state;
    show(jump, jumpOn, touchButtonCss('right'), flying ? 'Up' : 'Jump');
    show(fly, flyOn, touchButtonCss('right', undefined, TOUCH_BUTTON_BOTTOM_PX + TOUCH_BUTTON_PX + 12), flying ? 'Land' : 'Fly');
    show(down, flying, touchButtonCss('right', STICK_INSET_PX + STICK_BASE_PX + 12), 'Down');
  };
  refresh();

  // Document-level release fallback (see module header): a pointerup or
  // pointercancel that never reaches a base (no capture, finger/mouse off
  // the element) still releases the owning stick. Matching is by pointer id,
  // so this is a no-op for pointers no stick owns; when capture worked, the
  // base's own handler already released and this is a no-op too.
  const docRelease: Listener = (ev) => {
    move.endByEvent(ev);
    look.endByEvent(ev);
    for (const b of buttons) b.end(ev);
  };
  host.addEventListener('pointerup', docRelease);
  host.addEventListener('pointercancel', docRelease);
  // The page's stylesheets keep their cards and buttons clear of the sticks while this is set.
  host.documentElement?.setAttribute(TOUCH_MARK, '');

  let lastConsumeMs = now();
  let disposed = false;

  return {
    isPointerLocked: () => false,
    isKeyDown: () => false, // no keyboard on touch
    consumeJump(): boolean {
      const pressed = jumpPressed;
      jumpPressed = false;
      return pressed;
    },
    jumpHeld: () => jump.pointer !== null,
    descendHeld: () => down.pointer !== null,
    refresh,
    moveAxes(): MoveAxes {
      // Screen +y is down; stick UP means forward (+W). Right is +strafe
      // (+D). `|| 0` normalizes -0 away (the ±0 distinction leaks into
      // Object.is-based test equality and serves nothing here).
      return { forward: -move.y || 0, strafe: move.x };
    },
    consumeLookDelta(): LookDelta {
      // Once a frame: flight can begin or end, and a hint can change, without
      // anyone telling the buttons; `refresh` writes the page only on a change.
      refresh();
      const t = now();
      const elapsedS = Math.min(
        Math.max((t - lastConsumeMs) / 1000, 0),
        TOUCH_LOOK_MAX_CONSUME_S,
      );
      lastConsumeMs = t;
      // Stick right → positive yaw (turn right); stick down → positive pitch
      // (look down) — the same signs as desktop movementX/movementY, so the
      // controller's LOOK_SENSITIVITY_RAD_PER_PX applies unchanged.
      return {
        yawPx: look.x * TOUCH_LOOK_RATE_PX_PER_S * elapsedS,
        pitchPx: look.y * TOUCH_LOOK_RATE_PX_PER_S * elapsedS,
      };
    },
    dispose(): void {
      if (disposed) return;
      disposed = true;
      host.removeEventListener('pointerup', docRelease);
      host.removeEventListener('pointercancel', docRelease);
      for (const st of [move, look]) {
        for (const [type, listener] of st.registered) {
          st.base.removeEventListener(type, listener);
        }
        st.registered.length = 0;
        st.pointerId = null;
        st.x = 0;
        st.y = 0;
        st.base.remove();
        st.knob.remove();
      }
      for (const b of buttons) {
        for (const [type, listener] of b.registered) b.el.removeEventListener(type, listener);
        b.registered.length = 0;
        b.pointer = null;
        b.el.remove();
      }
      jumpPressed = false;
      host.documentElement?.removeAttribute(TOUCH_MARK);
    },
  };
}
